<?php use App\Services\LandingContentService as BlockCopy; ?>
<section class="nvl-section nvl-section-<?= e($blockType) ?>" id="landing-block-<?= e($blockType) ?>" data-component="<?= e($blockType) ?>" data-variant="<?= e($blockVariant) ?>"><div class="nvl-container">
<?php switch($blockType): case 'overview': ?>
<div class="nvl-overview"><header><span class="nvl-eyebrow">YEREL İHTİYAÇ, ORTAK VİZYON</span><h2><?= e($d['city']) ?> için çalışma kapsamı</h2><p class="nvl-disclosure"><?= icon('map-pin',15) ?> Hizmet bölgesi bilgisi, yerel ofis veya şube adresi değildir.</p></header><div class="nvl-prose"><?= BlockCopy::rich($d['local_context']) ?></div></div>
<?php break; case 'services': ?>
<header class="nvl-section-heading"><div><span class="nvl-eyebrow">HİZMETLERİMİZ</span><h2><?= e($d['services_title']?:'İhtiyacınıza uygun hizmetler') ?></h2></div><a href="/kategoriler">Tüm hizmetler <?= icon('arrow-up-right',15) ?></a></header>
<div class="nvl-service-grid"><?php foreach($landingServices as $n=>$service): ?><a class="nvl-service-card" href="/kategori/<?= rawurlencode($service['slug']) ?>"><span class="nvl-service-icon"><?= icon('layers',24) ?></span><small><?= sprintf('%02d',$n+1) ?></small><h3><?= e($service['name']) ?></h3><?php if(!empty($service['description'])): ?><p><?= e(excerpt(strip_tags($service['description']),145)) ?></p><?php endif; ?><strong>Hizmeti incele <?= icon('arrow-up-right',16) ?></strong></a><?php endforeach; ?></div>
<?php break; case 'scripts': case 'blog': case 'references':
$cards=$blockType==='scripts'?$landingScripts:($blockType==='blog'?$landingBlogs:$landingReferences);
$heading=$blockType==='scripts'?($d['scripts_title']?:'Hazır yazılım çözümleri'):($blockType==='blog'?($d['blog_title']?:'Rehberler ve içgörüler'):($d['references_title']?:'Seçili çalışmalarımız'));
?>
<header class="nvl-section-heading"><div><span class="nvl-eyebrow"><?= ['scripts'=>'HAZIR YAZILIMLAR','blog'=>'BİLGİ VE REHBER','references'=>'ÇALIŞMALARIMIZDAN'][$blockType] ?></span><h2><?= e($heading) ?></h2><?php if($blockType==='references'): ?><p>NetVera portföyünden örnekler; projelerin bu şehirde yapıldığı anlamına gelmez.</p><?php endif; ?></div><?php if($blockType!=='references'): ?><a href="<?= $blockType==='scripts'?'/hazir-scriptler':'/blog' ?>"><?= $blockType==='scripts'?'Yazılım kataloğu':'Tüm yazılar' ?> <?= icon('arrow-up-right',15) ?></a><?php endif; ?></header>
<div class="nvl-card-grid"><?php foreach($cards as $card):
$cardTitle=$card['title'];$cardImage=$blockType==='references'?\App\Services\RegionalLandingService::referenceImage($card):$card['image'];
$cardUrl=$blockType==='references'?\App\Services\SeoMetadataService::webUrl($card['url']??''):$card['url'];
$cardDescription=$blockType==='references'?($card['description']??''):$card['description'];
?><article class="nvl-card"><div class="nvl-card-media"><?php if($cardImage!==''): ?><img src="<?= e($cardImage) ?>" alt="<?= e(($card['image_alt']??'')?:$cardTitle) ?>" width="800" height="500" loading="lazy"><?php else: ?><span><?= icon($blockType==='scripts'?'code':'file-text',36) ?></span><?php endif; ?></div><div class="nvl-card-copy"><small><?= e($card['category']??'NETVERA PORTFÖYÜ') ?></small><h3><?php if($cardUrl): ?><a href="<?= e($cardUrl) ?>" <?= $blockType==='references'?'target="_blank" rel="noopener noreferrer"':'' ?>><?= e($cardTitle) ?></a><?php else: ?><?= e($cardTitle) ?><?php endif; ?></h3><p><?= e(excerpt(strip_tags($cardDescription),150)) ?></p><?php if($cardUrl): ?><a class="nvl-card-link" href="<?= e($cardUrl) ?>" <?= $blockType==='references'?'target="_blank" rel="noopener noreferrer"':'' ?>><?= ['scripts'=>'Yazılımı incele','blog'=>'Yazıyı oku','references'=>'Projeyi görüntüle'][$blockType] ?> <?= icon('arrow-up-right',16) ?></a><?php endif; ?></div></article><?php endforeach; ?></div>
<?php break; case 'content': ?>
<div class="nvl-articles"><?php foreach($d['sections'] as $n=>$item): ?><section class="nvl-article <?= $item['image']!==''?'nvl-article-illustrated':'' ?>" id="landing-section-<?= $n+1 ?>"><span class="nvl-step-number"><?= sprintf('%02d',$n+1) ?></span><div><h2><?= e($item['title']) ?></h2><div class="nvl-prose"><?= BlockCopy::rich($item['body']) ?></div><?php if($item['subheading']!==''): ?><h3><?= e($item['subheading']) ?></h3><div class="nvl-prose"><?= BlockCopy::rich($item['detail']) ?></div><?php endif; ?></div><?php if($item['image']!==''): ?><img src="<?= e($item['image']) ?>" alt="<?= e($item['alt']) ?>" width="1200" height="800" loading="lazy"><?php endif; ?></section><?php endforeach; ?></div>
<?php break; case 'answer': ?>
<div class="nvl-answer"><span class="nvl-answer-icon"><?= icon('message-circle',28) ?></span><div><span class="nvl-eyebrow">KISA VE NET</span><h2><?= e($seo['main_question']?:$d['service'].' hakkında bilmeniz gerekenler') ?></h2><div class="nvl-prose"><?= BlockCopy::rich($seo['direct_answer']?:$seo['geo_summary']) ?></div><?php if($seo['direct_answer']!==''&&$seo['geo_summary']!==''): ?><p><?= e($seo['geo_summary']) ?></p><?php endif; ?></div></div>
<?php break; case 'faq': ?>
<div class="nvl-faq-layout"><header><span class="nvl-eyebrow">SIK SORULAN SORULAR</span><h2><?= e($d['faq_title']?:'Merak ettikleriniz') ?></h2><a class="nvl-card-link" href="/iletisim">Sorunuzu bize iletin <?= icon('arrow-up-right',16) ?></a></header><div class="nvl-faq-grid"><?php foreach($d['faqs'] as $faq): ?><details><summary><?= e($faq['question']) ?><?= icon('plus',17) ?></summary><div class="nvl-prose"><?= BlockCopy::rich($faq['answer']) ?></div></details><?php endforeach; ?></div></div>
<?php break; endswitch; ?>
</div></section>
